quests[43089] = { id = 43089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Combatant's Plate Armor" }
quests[43090] = { id = 43090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulduars Schwur", description = "Ich war einst der Anführer aller von den Titanen geschaffenen Hüter in Azeroth. Die Titanen höchstpersönlich betrauten uns mit der Aufgabe, die Welt zu schützen.\n\nAls ich den Posten als Haupteinheit aufgab, verlor ich jeglichen Einfluss auf die anderen Hüter. Nicht einmal mein Sohn, Thorim, ist noch daran gebunden, meinen Befehlen Folge zu leisten.\n\nDas Gjallarhorn stammt allerdings aus einer Zeit vor unserem Zerwürfnis. Aus einer Zeit, in der ein uralter Ehreneid Bestand hatte.\n\nLasst uns diesen Eid anrufen. Ich bin sicher, dass Thorim dem Ruf Folge leisten wird.", sourceObjective = "Bittet Hymdall, das Gjallarhorn ertönen zu lassen, und fordert Thorims Unterstützung ein.", progress = "Welche Neuigkeiten gibt es aus Ulduar?", completion = "Ich danke Euch, {name}. Hodirs Tod ist bedauerlich, aber es hätte schlimmer kommen können. Dank Euch ist Ulduar heute nicht in die Hände der Legion gefallen.", sourceObjectiveStatus = "unverified-source-field" }
