quests[43100] = { id = 43100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach dem Szepter", description = "Sehr mächtig, aber schwer zu besorgen. Szepter ist im Besitz von Gul'dan. Wir müssen nahe an ihn heran, seine Pläne herausfinden.\n\nCalydus weiß, Gul'dan plant etwas Großes. Hat den ganzen Schattenrat zu den Waffen gerufen, um bei wichtigem Ritual zu helfen. Eine der Gruppen ist bei Darrowehr und spricht dort mit den Totenbeschwörern.\n\nIhr solltet gehen und mehr über den Plan herausfinden.", sourceObjective = "Begebt Euch nach Darrowehr in den Westlichen Pestländern und findet etwas über das Ritual des Schattenrats heraus.", progress = "Das wird kompliziert, aber Calydus hat eine Idee!", completion = "Gul'dan sagt, alle mit Macht können mitmachen. Und wenn Freund mitmacht? Dann schnappen wir Szepter und laufen los!\n\nJa! Könnte gehen, aber braucht harte Arbeit, um Vertrauen zu gewinnen. Gul'dan braucht immer noch Auge. Freund sollte ihm dabei helfen und sich mehr Respekt verdienen.", sourceObjectiveStatus = "unverified-source-field" }
