quests[43150] = { id = 43150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar Collapse Scenario - Treasure 09 - Focus Attacks 03" }
quests[43151] = { id = 43151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angebot und Nachfrage", description = "Ja, ich habe Unvergänglichkeitshopfen, aber ich habe lange gebraucht, um ihn zu sammeln. Ich kann ihn nicht einfach so abgeben.\n\nAllerdings bin ich bereit, ihn gegen Steinbalgleder zu tauschen.\n\nSolltet Ihr davon etwas finden, bringt es mir und wir können einen Tauschhandel machen.", sourceObjective = "Beschafft 20 Stücke Steinbalgleder.", progress = "Habt Ihr Leder zum Tausch?", completion = "Ich danke Euch, {class}. Ich werde das Beste daraus machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43152] = { id = 43152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Lytheron" }
quests[43153] = { id = 43153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Szepter", description = "Klingt einfach? <Freund/Freundin> muss sich gut stellen mit dem Schattenrat... vorerst. Helft mit dem Ritual, bis Ihr Vertrauen gewonnen habt, und dann zeigt wahres Gesicht!\n\nRat hat hier Portalapparatur nach Tol Barad gebaut. Geht und helft Schattenrat, Auge von Dalaran zu finden, verdient Euch guten Platz beim Ritual! Und dann stehlt das Szepter!\n\nCalydus versucht, <Freund/Freundin> im Auge zu behalten, wenn möglich.", sourceObjective = "Nehmt das Portal nach Tol Barad und helft bei der Suche nach dem Auge von Dalaran.", completion = "Ja, ja! Habt das Auge gefunden! Große Hilfe für Schattenrat! Und nun geht zum Ritual. Szepter ist dort.\n\nWird kniffelig, mein Freund, aber Calydus weiß, Ihr schafft das!", sourceObjectiveStatus = "unverified-source-field" }
