quests[43161] = { id = 43161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warmongering Gladiator's Felweave Armor" }
quests[43162] = { id = 43162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem verwachsenen Baum", description = "Meine drei Schwestern wurden gehenkt,\nIhrer Unschuld kein Glauben geschenkt,\nDoch die jüngste, sie konnte entkommen,\nHat den losen Strick von ihrem Nacken genommen,\nDer alte Rabenkrone trat unsere Ehre mit Füßen,\nDer Fluch gebietet es, er soll nun büßen.", sourceObjective = "Trinkt vom Kessel der Hexe, um ihren Fluch anzunehmen und den Geist ihrer ruhelosen Schwester zu besiegen.", progress = "Macht Euch bereit, Ihr müsst jetzt trinken,\n\nLasst meine Schwester wieder in den Schlaf versinken.", completion = "Meine geliebte Schwester ruht jetzt in Frieden,\nEin tapferer Held hat diese Schlacht entschieden,\nHeute wird er enden, der böse Fluch,\nUnd für Euch wird er sich lohnen, der Besuch,\nDie anderen Schwestern werden nie mehr sprechen,\nDoch eines Tages, da werde ich mich rächen.", sourceObjectiveStatus = "unverified-source-field" }
