quests[43179] = { id = 43179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kirin Tor von Dalaran", description = "Unterstützt die Kirin Tor von Dalaran, indem Ihr 3 Weltquests abschließt.", sourceObjective = "Schließt 3 Weltquests der Kirin Tor ab.", completion = "Die Kirin Tor danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[43181] = { id = 43181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Szepter", description = "Das Logbuch enthält die neuesten Informationen über das Szepter des Sargeras. Anscheinend wurde es von einem sehr nervösen, aufgeregten oder übergeschnappten Wichtel verfasst und ist kaum lesbar. Bringt es Calydus, damit er es übersetzen kann.", sourceObjective = "Bringt das Logbuch zu Calydus in der Schreckensnarbe.", sourceObjectiveStatus = "unverified-source-field" }
quests[43182] = { id = 43182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das vermisste Gefäß", description = "Solange Hakkar sich frei herumtreibt, ist kein Magier in Sicherheit.\n\nMillificent Manasturm hat ein Gefäß erschaffen, das einem Magier die Essenz entzieht und seine Magie an das Objekt bindet. Es war als Waffe gedacht, aber wir können es als Köder verwenden.\n\nWenn ich meine Essenz in das Gefäß kanalisiere, wird daraus ein Objekt aus reiner Magie.\n\nMillificent hat das Gefäß zertrümmert, als sie gefangen genommen wurde, und es so unseren Feinden in die Hände fallen lassen.\n\nFindet die Teile und bringt sie zu mir zurück. Zusammen können wir eine Falle aufstellen, der Hakkar nicht widerstehen können wird!", sourceObjective = "Interagiert mit der Späherkarte und schließt die Missionen der Reihe \"Das vermisste Gefäß\" ab, um Bruchstücke des zertrümmerten Gefäßes zu sammeln.", progress = "Habt Ihr die fehlenden Teile schon gefunden?", completion = "Ich bin erleichtert, dass diese vernichtende Waffe sich nicht mehr in den Händen unserer Feinde befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[43183] = { id = 43183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm der Wächterinnen: Die Sternenjägerwacht" }
quests[43184] = { id = 43184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Allari die Seelenfresserin", sourceObjective = "Wie geschickt von Euch, Euch das Beste für den Schluss aufzuheben.\n\n<Allari grinst schelmisch.>\n\nGanz im Ernst, ich fühle mich sehr geehrt, dass Ihr mich ausgewählt habt, {name}. Ich habe das Gefühl, dass uns das Schlimmste noch bevorsteht. Wir müssen wachsam bleiben und der Brennenden Legion ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43185] = { id = 43185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Jace Düsterweber", sourceObjective = "Mich? Ihr wollt mich als einen Eurer Champions?\n\nNatürlich. Ja, ja, auf jeden Fall! Sagt mir einfach, wo ich hingehen und was ich tun soll, dann könnt Ihr es als erledigt ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43186] = { id = 43186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin der Rächer!", description = "{name}, wir sind hier versammelt, um Eure Erfolge als <unser Anführer/unsere Anführerin> sowie die von Euch erbrachten Opfer zu würdigen.", sourceObjective = "Hört zu, während die Illidari und Illidans Diener Euch würdigen.", completion = "Mit Euch als Anführer haben wir einen Sieg nach dem anderen erstritten. Wir dienen Euch mit Freuden und sind bereit, alles in Eurem Namen zu opfern.\n\nEhre sei Rächer {name}!", sourceObjectiveStatus = "unverified-source-field" }
