quests[43248] = { id = 43248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm der Wächterinnen: Finsterfolgs Turm" }
quests[43249] = { id = 43249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rabenauge", description = "Wir müssen den Brief des SI:7 unbedingt entschlüsseln und seine Geheimnisse lüften, bevor es zu spät ist. Doch auch unsere besten Experten haben noch keinerlei Fortschritte bei der Dechiffrierung gemacht.\n\nWir wissen jetzt aber, dass der Mythos wahr ist. Das Rabenauge gibt es wirklich.\n\nSollen wir das den anderen sagen?", sourceObjective = "Hört Valeeras Erzählung über das Rabenauge zu.", completion = "Was haltet Ihr nun davon, mit mir nach Val'sharah zu gehen und das mächtigste Juwel zu bergen, das es gibt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43250] = { id = 43250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An den Hof", description = "Der Rabenhof der Rabenwehr ist der Ausgangspunkt unserer Suche. Er ist die Heimat der Ahnen von Lord Kur'talos Rabenkrone, Held der Nachtelfen im Krieg der Ahnen. Einige meiner eigenen Vorfahren liegen auf dem dortigen Friedhof begraben.\n\nTrefft mich dort und achtet darauf, dass Euch niemand folgt. Der SI:7 versteht sich sehr gut auf seine Arbeit. Wir müssen besser sein.", sourceObjective = "Trefft Euch mit Valeera Sanguinar am Rabenhof in Val'sharah.", completion = "Jetzt, da Ihr endlich hier seid, können wir beginnen.\n\nDie Elfen hier wurden irgendwie von den Toten erweckt. Sie leiden unter Wahnvorstellungen. Sie glauben, dass wir die Brennende Legion sind, gekommen, um die Rabenwehr zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[43251] = { id = 43251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Auge", description = "Das Rabenauge sollte immer noch irgendwo im Bereich des Hofs sein. Hier haben Rabenkrone und seine Offiziere zu Lebzeiten ihre Strategien geplant. Womöglich tun sie es jetzt immer noch.\n\nEs muss hier irgendwo sein. Eure Fertigkeiten im Schlossknacken sollten dabei sehr nützlich sein.", sourceObjective = "Knackt die Schlösser uralter Truhen, um das Rabenauge zu finden.", progress = "Habt Ihr das Rabenauge schon gefunden?", completion = "Ein Buch? Lasst mich mal sehen.\n\n<Valeera greift nach dem Folianten und fängt an, ihn durchzublättern.>\n\nDas ist der Schlüssel!", sourceObjectiveStatus = "unverified-source-field" }
quests[43252] = { id = 43252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Unruhe", description = "Meine Urahnen liegen auf dem Friedhof westlich von hier begraben. Was auch immer die Toten dort auferweckt, hat auch ihre Seelen in Unruhe versetzt.\n\nAlle Blutelfen stammen von Hochelfen ab, die wiederum aus diesen Landen vor der Zerschlagung stammen.\n\nIch kann mich nicht dazu überwinden. Schenkt Ihr meinen Ahnen die ewige Ruhe?", sourceObjective = "Schenkt Cesta Sternenspäher, Mandrel Nachtbann und T'rel Mondklinge die ewige Ruhe.", completion = "Ich danke Euch, {name}. Es bedeutet mir viel, dass Ihr meinen Urahnen den verdienten Frieden geschenkt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[43253] = { id = 43253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Uralte Vrykullegenden", description = "Unsere Ablenkungstaktiken in Sturmheim haben uns Informationen zu etwas verschafft, das ich bisher für einen Mythos gehalten hatte.\n\nEs gibt eine Legende über ein magisches Juwel, das die Vrykul lange, bevor es Menschen gab, erschaffen haben. Das Juwel war angeblich in der Lage...\n\n<Valeera unterbricht sich, sieht sich um und beäugt Euch verschmitzt.>\n\nNoch will ich lieber nicht davon sprechen. Erst, wenn wir Beweise haben.\n\nLeider gibt es nur eine Möglichkeit, Beweise zu finden: auf der Naglfar im Seelenschlund... dem Schiff der Toten.", sourceObjective = "Stellt eine Gruppe zusammen und besorgt einen Abdruck der Rabenaugentafel auf der Naglfar, dem Schiff der Toten, im Seelenschlund.", completion = "Die Legende ist also wahr! Ich lag mit meinen Vermutungen richtig. Ich hatte von Rabenkrones nahezu perfekten Spionen während des Kriegs der Ahnen gehört. Jetzt wissen wir, wie sie an ihre Informationen gelangt sind.\n\nDas werden uns die anderen nicht glauben. Wir könnten es natürlich auch für uns behalten.\n\n<Valeera hält einen Moment inne, um das zu erwägen.>\n\nNein. Das ist der Untergang der Narren und Gierigen. Wir werden das Risiko auf alle verteilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43254] = { id = 43254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ruinierte Ritual", description = "Jetzt geht es um alles, <Freund/Freundin>! Gul'dan will mit dem Ritual beginnen und das Ende der Welt einläuten. Calydus weiß, das Szepter wird das verhindern.\n\nNehmt diese Fledermaus, geht zum Grabmal des Sargeras, sucht die Ritualstätte, stehlt das Szepter. Oh... Und dann entkommt!\n\nCalydus hilft, so gut er kann. Viel Glück, <Freund/Freundin>!", sourceObjective = "Reist auf der Teufelsfledermaus zum Grabmal des Sargeras und stehlt das Szepter des Sargeras.", completion = "Calydus kann es nicht glauben... Es hat geklappt! Ritual vereitelt, Schattenrat vernichtet und wir leben noch!\n\nOh, und Ihr habt das Szepter! Ein großer Sieg, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[43255] = { id = 43255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 061 - Nastrondir" }
quests[43259] = { id = 43259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung vor dem verwachsenen Baum", description = "Ich muss Euch warnen, {race}. Val'sharah wird von einer starken und finsteren Macht heimgesucht. Ich habe sie gesehen und ich wünschte, dass es mir nicht widerfahren wäre. Ich möchte Euch raten, Euch vom verwachsenen Baum in Bradenbach fernzuhalten.", sourceObjective = "Untersucht den verwachsenen Baum in Bradenbach.", completion = "Zum verwachsenen Baum Ihr seid gekommen,\n\nEinen Feind zu finden, Ihr habt Euch vorgenommen,\n\nAber hört zuvor, welch Unrecht sich zugetragen,\n\nZeigt Erbarmen mit meiner Schwester Klagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[43261] = { id = 43261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Vanessa van Cleef", sourceObjective = "Nach alledem wollt Ihr mich als Euren Champion?\n\n<Vanessa wirft Euch einen ungläubigen Blick zu und zögert eine Weile, bevor sie antwortet.>\n\nAlso schön, aber ich mache die Dinge auf meine Art. Einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[43262] = { id = 43262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Garona die Halborcin", sourceObjective = "<Garona dreht eine ihrer rasiermesserscharfen Klingen in ihren Fingern, bevor sie sie geschickt in ihrem Gürtelbund verschwinden lässt.>\n\nSolange es dabei etwas zum Töten gibt, könnt Ihr mich gern auf Eure kleinen Missionen schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[43264] = { id = 43264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Ihr verfügt über große Macht, <Todesgebieter/Todesgebieterin>. Aber Macht allein ist manchmal nicht ausreichend.\n\nUm diese Welt vor der Brennende Legion zu retten, benötigt Ihr mächtige Verbündete. Die Ritter der Schwarzen Klinge unterstehen Eurem Befehl. Ihr solltet also lernen, sie effizient einzusetzen.\n\nGeht und sprecht mit Nazgrim und Thassarian. Sie werden Euch im Kampf gegen die Brennende Legion eine große Hilfe sein.", sourceObjective = "Rekrutiert Nazgrim und Thassarian.", completion = "Gut gemacht, Todesgebieter. Nazgrim und Thassarian sind mächtige Champions. Ich bin mir sicher, dass sie ihre Befehle mit tödlicher Präzision ausführen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43265] = { id = 43265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitet die Kunde", description = "Nachdem Ihr jetzt die Champions rekrutiert habt, könnt Ihr mithilfe der Späherkarte wichtige Missionen im ganzen Gebiet der Verheerten Inseln ausführen.\n\nDie erste Mission ist besonders wichtig, um unseren Orden größer und stärker zu machen. Schickt Nazgrim und Thassarian los, um nach neuen Kandidaten für die Schwarze Klinge zu suchen.\n\nUnser Orden muss noch viel stärker werden, wenn wir die Brennende Legion besiegen wollen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Verbreitet die Kunde\" ab.", progress = "Wie verläuft die Mission?", completion = "Nazgrim und Thassarian waren anscheinend erfolgreich mit ihrer Mission. Wir haben ein paar vielversprechende Kandidaten gefunden, die uns im Krieg gegen die Brennende Legion behilflich sein könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43266] = { id = 43266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Truppen", description = "Ein mächtiger Totenbeschwörer hat sich der Schwarzen Klinge angeschlossen.\n\nDer dunkle Beschwörer Marogh hat den langen Weg aus dem Reich der Schattenlande auf sich genommen, um sich uns anzuschließen. Er wird einen wertvollen Verbündeten für die Schwarze Klinge abgeben.\n\nSprecht mit dem dunklen Beschwörer Marogh, um damit zu beginnen, eine Armee Ghule für die Schwarze Klinge aufzustellen.", sourceObjective = "Sprecht mit dem dunklen Beschwörer Marogh, um Ghule zu beschwören.", progress = "Hat der dunkle Beschwörer Marogh seine Arbeit aufgenommen?", completion = "Gute Arbeit, Todesgebieter.\n\nDiese Ghule werden beim Kampf auf den Verheerten Inseln von unschätzbarem Wert sein. Schickt sie auf Missionen, wie Eure anderen Champions auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[43267] = { id = 43267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen im Feld", description = "Es ist Zeit, Eure frisch herbeigerufenen Ghule ins Feld zu schicken. Betrachtet den Befehlstisch und entsendet Eure Champions und Truppen auf eine Routineerkundungsmission.", sourceObjective = "Benutzt den Befehlstisch und schließt die Mission \"Truppen im Feld\" ab.", completion = "Ausgezeichnete Arbeit, Todesgebieter. Die Mission war ein voller Erfolg.\n\nMit dieser Art Unterstützung werden wir die Brennende Legion sicher bald zurückschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43268] = { id = 43268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen aufrüsten, bitte", description = "Archivar Zubashi hat die Nekropolis, die wir Acherus nennen, umfassend erforscht.\n\nDurch seine Studien über die Nekropolis konnte er eine Reihe potenzieller Verbesserungen bestimmen, von denen die Schwarze Klinge deutlich profitieren würde.\n\nSprecht jetzt mit Archivar Zubashi und lasst Euch von ihm diese Verbesserungen aufzeigen.", sourceObjective = "Sprecht mit Archivar Zubashi in Acherus.", completion = "Eine ausgezeichnete Entscheidung, Todesgebieter. Sprecht einfach mit Zubashi, wenn Ihr weitere Veränderungen wünscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[43270] = { id = 43270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Als <Anführer/Anführerin> unseres Ordens seid Ihr ein Vorbild für die anderen Priester. Viele von ihnen werden Euch treuen Dienst schwören und alles tun, um die Brennende Legion in die Knie zu zwingen.\n\nNachdem Ihr Eure Macht während des Läuterungsrituals gezeigt habt, gibt es viele, die gerne an Eurer Seite dienen möchten. Wendet Euch an diese Priester und lasst Euch einen Teil der Last auf Euren Schultern abnehmen.", sourceObjective = "Rekrutiert Calia Menethil und Hohepriesterin Ishanah.", completion = "Ausgezeichnet. Calia Menethil und Hohepriesterin Ishanah sind würdige Champions. Wir können ihnen jede erdenkliche Aufgabe anvertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43271] = { id = 43271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Calia Menethil", sourceObjective = "Seid gegrüßt, {name}. Es ist eine Ehre, an Eurer Seite dienen zu dürfen.\n\nIch helfe Euch gerne, sofern ich es kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[43272] = { id = 43272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hohepriesterin Ishanah", completion = "Eure Bemühungen, Saa'ra wieder zu altem Glanz zu verhelfen, sind nicht unbemerkt geblieben. Als bescheidene Dienerin der Sha'tar danke ich Euch.\n\nAls Anführerin der Aldor ist es meine Pflicht, alles Heilige zu bewahren. Dieser Tempel ist eine Flamme des Glaubens, die beschützt werden muss.\n\nIhr könnt mich zu Euren Verbündeten zählen. Auch ich bin bereit, alles zu tun, um die Brennende Legion zu vernichten." }
quests[43273] = { id = 43273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitet die Kunde", description = "In der Mitte des Podiums befindet sich eine Karte der Verheerten Inseln. Mit ihrer Hilfe könnt Ihr unsere Verbündeten auf wichtige Missionen in der ganzen Welt schicken.\n\nDer erste Auftrag ist entscheidend für das Wachstum unseres Ordens. Wir müssen ein paar fähige Priester finden, denen wir die Ausbildung unserer Ordenstruppen anvertrauen können.\n\nEiner unserer neuen Champions ist sicherlich in der Lage, diese Aufgabe zu übernehmen.", sourceObjective = "Benutzt die Schlachtkarte und schließt die Mission \"Verbreitet die Kunde\" ab.", completion = "Calias Mission war ein Erfolg! Bald sehen wir hier womöglich einige neue Gesichter.", sourceObjectiveStatus = "unverified-source-field" }
quests[43275] = { id = 43275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Truppen", description = "Unsere Rekrutierungsbemühungen haben sich gelohnt. Großanachoret Gesslar hat sich in den Dienst dieses Ordens gestellt.\n\nEr hat ein Auge für Potenzial und kann Rekruten leicht erkennen, die womöglich Großartiges erreichen können. Er nimmt die Auserwählten unter seine Fittiche und macht aus ihnen würdige Verbündete.\n\nSprecht jetzt mit ihm und bildet eine Truppe Akolythen aus.", sourceObjective = "Sprecht mit Großanachoret Gesslar und bildet eine Truppe Akolythen aus.", completion = "Ausgezeichnet. Diese Trupps werden bei der Verteidigung der Verheerten Inseln unschätzbare Dienste leisten. Ihr könnt sie genauso auf Missionen schicken wie die Champions.", sourceObjectiveStatus = "unverified-source-field" }
quests[43276] = { id = 43276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen im Feld", description = "Es ist Zeit, Eure frisch ausgebildeten Akolythen ins Feld zu schicken. Betrachtet die Schlachtkarte und entsendet Eure Champions und Trupps auf eine Routineerkundungsmission.", sourceObjective = "Benutzt die Schlachtkarte und schließt die Mission \"Trupps in Ausbildung\" ab.", completion = "Die Erkundungsmission war noch erfolgreicher, als wir uns hätten vorstellen können, {name}.\n\nEure Truppen konnten Archon Torias retten, einen fähigen Forscher, dessen Wissen weit über Licht und Schatten hinausreicht.\n\nAus Dankbarkeit hat er sich bereit erklärt, sein Wissen für unsere Sache zur Verfügung zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43277] = { id = 43277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen aufrüsten, bitte", description = "Wir haben großes Glück, Archon Torias gefunden zu haben.\n\nSein Wissen wird unschätzbar wertvoll sein, wenn wir unsere Verteidiger stärken und den Netherlichttempel befestigen wollen.", sourceObjective = "Sprecht mit Archon Torias im Netherlichttempel.", progress = "Hattet Ihr schon Gelegenheit, mit Archon Torias zu sprechen?", completion = "Eine hervorragende Wahl, {name}. Archon Torias wird seine Forschung im Netherlichttempel fortsetzen. Sprecht mit ihm, wenn Ihr weitere Aufwertungen vornehmen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[43278] = { id = 43278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felforged Plate Armor" }
