quests[43302] = { id = 43302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 066 - Outskirts" }
quests[43303] = { id = 43303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reif für Randale!", description = "Willkommen zur Rabenwehrrandale! Es haben schon viele Kämpfer in der Arena der Rabenwehr teilgenommen, um ihre Stärke unter Beweis zu stellen, und jetzt seid Ihr an der Reihe.", sourceObjective = "Sprecht mit David Globetrotter und findet heraus, wie man an der Rabenwehrrandale teilnimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[43304] = { id = 43304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 067 - Outskirts" }
quests[43305] = { id = 43305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 068 - Haustvald" }
quests[43306] = { id = 43306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 069 - Haustvald" }
quests[43307] = { id = 43307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 070 - Outskirts" }
quests[43308] = { id = 43308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 071 - Outskirts" }
quests[43309] = { id = 43309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Gelegenheit", description = "Ich habe Gerüchte aus Suramar vernommen.\n\nNach den jüngsten Unruhen in der Stadt wollen die Adeligen Elisandes Rat um einen zusätzlichen Berater erweitern. Solche Posten werden äußerst selten angeboten und sind daher heiß begehrt.\n\nDies ist die perfekte Gelegenheit und Ly'leth ist die perfekte Kandidatin. Das Schicksal meint es gut mit uns!\n\nIch weiß, dass sie in der Vergangenheit geschworen hat, sich aus politischen Ränkespielchen herauszuhalten, aber jetzt müssen wir sie bitten, anzutreten.\n\nSucht sie am Mondsichelforum auf und sorgt dafür, dass die Wahl auf sie fällt.", sourceObjective = "Trefft Euch mit Ly'leth Lunastre am Mondsichelforum.", progress = "Ein großer Gefallen, um den mich Thalyssra bittet.", completion = "Ah, {name}.\n\nIch freue mich, Euch wiederzusehen. Ich hoffe, Ihr seid bereit, mich bei meiner Kampagne zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43310] = { id = 43310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweder für uns", description = "Thalyssra verlangt viel von mir, aber unsere Sache ist das Risiko wert.\n\nDie Position des Beraters würde uns enormen Einfluss verschaffen - und Informationen. Verschlossene Türen öffnen.\n\nIch könnte den Lauf dieser Rebellion verändern. Ich könnte so viele Leben retten.\n\nAber ich werde starke Unterstützer brauchen. Aufgrund des guten Rufs meiner Familie stehen viele der Häuser hinter mir, andere wiederum zögern noch.\n\nDazu gehört zum Beispiel auch Lady Aurore vom Haus Astravar. Sucht sie auf und bietet ihr in meinem Namen Hilfe an.\n\nGewinnt ihr Vertrauen. Der Rest ist dann nur noch Formsache.", sourceObjective = "Sprecht mit Lady Aurore.", completion = "Ich liebe Lady Lunastre wie eine Schwester, aber ich fürchte, mir sind die Hände gebunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43311] = { id = 43311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oder gegen uns", description = "Wenn Ly'leth die Beraterin der Großmagistrix werden will, müssen wir ihr den Weg ebnen.\n\nIn der Tat wird sie einige Unterstützer haben, aber die allein können ihr nicht den Titel sichern.\n\nLy'leth muss sich noch mit anderen Häusern auseinandersetzen, deren bevorzugte Werkzeuge Furcht und Zwang sind. Niemand wagt es, sie offen zu bekämpfen, und mit Gefälligkeiten und Versprechen werden wir sie nicht überzeugen können.\n\nSucht Arluin auf. Er hat sicherlich ein paar gute Ideen für uns.", sourceObjective = "Sprecht mit Arluin.", completion = "Also gut. Besprechen wir die Vorgehensweise.", sourceObjectiveStatus = "unverified-source-field" }
quests[43312] = { id = 43312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fast unverhohlene Drohungen", description = "Wie konnte ich das nur zulassen?\n\n<Aurore ringt die Hände.>\n\nGestern hat mich Coryn Stelleris wegen der Abstimmung angesprochen. Er wollte meine Unterstützung, aber ich habe sie ihm nicht gewährt.\n\nEr sagte, mein Sohn könne ganz normal weiterleben, ich müsste ihm lediglich meine Stimme geben.\n\nUnd heute Morgen war mein Sohn verschwunden.\n\nIch mag mir gar nicht ausmalen, was für furchtbare Dinge sie mit ihm anstellen. Ihr wisst, wozu diese Familie fähig ist!\n\nAuch Ihr möchtet meine Unterstützung, aber ich kann nichts tun, solange mein Sohn in Gefahr ist. Gar nichts.\n\nBitte... rettet ihn!", sourceObjective = "Rettet Ailen Astravar.", progress = "Habt Ihr meinen Sohn gefunden?", completion = "Er ist unversehrt! Ich stehe tief in Eurer und Ly'leths Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[43313] = { id = 43313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerüchte sind Waffen", description = "Coryn Stelleris und Ruven Dämmermaar waren eng befreundet, aber einer hat immer den anderen in den Schatten gestellt. Jetzt kann die Familie Stelleris viel durch Lord Ruvens Tod gewinnen. Sehr viel.\n\nHaus Dämmermaar wird schon bald von dem Verlust erfahren. Ich möchte, dass Ihr ihre Wut und Trauer in für uns vorteilhafte Bahnen lenkt.\n\nDazu braucht es nur ein paar geschickt gestreute Gerüchte.\n\nIch werde mich nicht lange in diesem Teil der Stadt aufhalten und Ly'leth ist sicher sehr an Euren Fortschritten interessiert.\n\nKehrt zu ihr zurück, wenn Ihr diese Aufgabe erledigt habt.", sourceObjective = "Streut Gerüchte unter den Mitgliedern von Haus Dämmermaar.", completion = "In der Stadt kursieren die interessantesten Gerüchte, {name}. Der Sieg rückt immer näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[43314] = { id = 43314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: Fürchtet den Zorn eines geduldigen Elfen", description = "Es hat sich eine Gelegenheit ergeben, {name}.\n\nLy'leth hat dafür gesorgt, dass Ihr Zutritt zu einem Ball am Hof der Sterne erhaltet. Ich weiß nicht, ob uns dieses Unterfangen weiterhelfen wird, aber ich möchte Euch mit einer Aufgabe betrauen.\n\nBerater Melandrus und ich waren früher Verbündete. Zusammen hatten wir Elisandes Sturz geplant, aber als der Zeitpunkt gekommen war, hat er mich verraten.\n\nDie Wunde, die er mir mit seinem Dolch zugefügt hat, schmerzt mich noch immer. Ich selbst kann Suramar nicht betreten, um Rache zu nehmen, aber Ihr.\n\nRichtet ihn wie einen Verräter hin und bringt mir seinen Zauberstein.", sourceObjective = "Betretet den Dungeon \"Der Hof der Sterne\" und tötet Berater Melandrus. Nehmt ihm seinen Zauberstein ab und bringt ihn Thalyssra.", progress = "Ist es vollbracht?", completion = "<Für einen Moment umfasst Thalyssra den Zauberstein ganz fest.>\n\nEr hat es nicht anders gewollt.\n\nIch muss die Vergangenheit ruhen lassen. Durch seinen Verlust haben wir Elisande geschwächt und sind dem Ziel, Rache für die Shal'dorei zu nehmen, einen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43315] = { id = 43315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Tode geweiht", description = "Es gibt zwei Häuser, die Ly'leths Aufstieg gefährden könnten, aber vorerst kümmern wir uns nur um eines von ihnen.\n\nDas Haus Dämmermaar hat sich sein Ansehen durch Furcht verschafft, und das nicht ohne Grund. Es gibt nur wenige, die über so viel magisches Talent verfügen wie Ruven Dämmermaar.\n\nOhne ihren herausragenden Vertreter aber ist das Haus bedeutungslos.\n\nVielleicht haltet Ihr meine Methoden für verwerflich. Aber Ihr solltet wissen, dass es schon lange vor der Legion Dämonen in Suramar gegeben hat.\n\nUnd dieser hier hat schon lange genug gelebt.", sourceObjective = "Tötet Ruven Dämmermaar.", progress = "Ist es vollbracht?", completion = "Es schien, als hättet Ihr das Problem voll im Griff. Ich wollte Euch... nicht stören.\n\nEin machthungriges Blaublut weniger, um das wir uns sorgen müssen. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43317] = { id = 43317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschafft", description = "Alle in der Stadt sind aufgebracht.\n\nIch werde Euch nicht anlügen. Ich bin hocherfreut, dass jemand wie Coryn sich blamiert.\n\nDie anderen Häuser haben mir ihre Unterstützung zugesichert. Es ist vollbracht. Jetzt muss nur noch eine offizielle Amtseinführung stattfinden, bei der mir der Titel der Beraterin verliehen wird.\n\nIch sehe Euch dort. Ihr verdient es, an diesem Erfolg teilzuhaben.", sourceObjective = "Wohnt Ly'leth Lunastres Aufstieg zur Beraterin bei.", progress = "Ich bin bereit. Die Zeit ist nah.", completion = "Dies könnte unschöner enden, als ich es mir gewünscht hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[43318] = { id = 43318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ly'leths Champion", description = "Tal'ashar ist ein Ehrenduell.\n\nWenn ich verliere, muss ich meinen Titel an Coryn Stelleris abtreten.\n\n<Ly'leth lächelt sanft.>\n\nAus dem Grund müsst Ihr für mich kämpfen.\n\nFür diese Aufgabe werde ich Euch eine mächtigere Verkleidung überlassen, und gemeinsam werden wir Coryn in seine Schranken weisen.\n\nSprecht mit mir, wenn Ihr bereit seid, in meinem Namen zu kämpfen.", sourceObjective = "Sprecht mit Ly'leth, um mit der Begegnung zu beginnen.", progress = "Ich weiß, Ihr werdet meine Ehre verteidigen, {name}.", completion = "Wir haben heute große Fortschritte gemacht. Das werde ich nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43319] = { id = 43319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Tigers", description = "Unter den Verbündeten vom Tiankloster, die sich uns angeschlossen haben, ist Gin Lai. Er ist ein Mönch, der für seine Erfahrung auf dem Weg des Tigers berühmt ist.\n\nMit seiner Hilfe können wir Tigerinitianden ausbilden, die schnell und präzise auf dem Schlachtfeld zuschlagen.\n\nMacht Euch sofort auf, sprecht mit ihm und erbittet seine Dienste.", sourceObjective = "Sprecht mit Rekrutierer Gin Lai.", completion = "Ich werde mein Bestes geben, um den Weg des Tigers zu lehren, Großmeister: den Feind beobachten und dann ohne Zögern zuschlagen. Bald werden unseren Initianden bereit für den Kampf sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[43323] = { id = 43323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Reflektierens", description = "Es ist an der Zeit, dass wir uns die Ereignisse, die zu diesem Moment geführt haben, in Erinnerung rufen: eine Würdigung unserer großen Geschichte und der Begebenheiten, die sie prägten.", sourceObjective = "Gebt die richtige Antwort auf eine von Llores Fragen zur Geschichte von Azeroth.", progress = "So lasst uns über die Ereignisse sprechen, die bereits geschehen sind.", completion = "Ein Moment der Rückbesinnung auf unsere Erfolge. Ein Tag, an dem wir in die Zukunft und auf unsere Bestimmung blicken. Ein Jahr der Rückschau darauf, was es bedeutet, zu wachsen, und eine Lebensspanne an Erinnerungen für jene, die tapfer ihren Weg gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43324] = { id = 43324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Eulenbestien" }
quests[43325] = { id = 43325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyrennen" }
quests[43327] = { id = 43327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Magie des Flugs" }
quests[43328] = { id = 43328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvoll" }
quests[43331] = { id = 43331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahltag", description = "Heda, <Freund/Teuerste>. Meine hiesigen Quellen berichten, dass Ihr eine Auseinandersetzung mit den Gebrüdern Sechszünder hattet. Ihr scheint wohl einige Probleme mit ihnen zu haben?\n\nAlso, ich würde sie auch nicht zu meinen Freunden zählen.\n\nIn diesem Sinne: Wie wäre es, wenn ich Euch ein paar geheime Informationen über ihren aktuellen Aufenthaltsort verrate? Vielleicht wird ihnen ja demnächst etwas zustoßen, wenn Ihr wisst, was ich meine?\n\nOh, und bringt ein paar Freunde mit. Sie zählen nicht zu den einfachsten Zielen.", sourceObjective = "Besorgt den Schlüssel der Sechszünders von Rax Sechszünder in Sturmheim.", progress = "Dies scheint der Ort zu sein, wo die Gebrüder Sechszünder ihr wertvollstes Raubgut verwahren.", completion = "Nach dem Tod der Gebrüder Sechszünder könnt Ihr endlich den verdienten Lohn für Eure Dienste einstreichen.\n\nIhr durchwühlt ihre wertvollsten Besitztümer und nehmt Euch, was Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[43332] = { id = 43332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grell im Körbchen" }
quests[43333] = { id = 43333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Nylaathria die Vergessene" }
quests[43334] = { id = 43334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der aufziehende Sturm", description = "Ihr habt uns alle gerettet! Ihr verkörpert wirklich alles, wofür die Elemente stehen.\n\nWenn der Irdene Ring obsiegen soll, benötigen wir mächtige Waffen. Ich weiß, wo man solche Waffen finden kann. Nach dem Pandarenfeldzug wurden die Waffen des Sturmgottes Ra-den unter dem Thron des Donners entdeckt. Sie sind so mächtig, dass sie bislang niemand beherrschen konnte.\n\nSie wurden in die Obhut des Weißen Tigers gegeben, der sie nur jenen überlassen wird, die sich ihrer würdig erweisen. Kommt, {name}! Lasst uns nach Pandaria aufbrechen und beweisen, dass Ihr würdig seid!", sourceObjective = "Reist nach Pandaria und sprecht mit dem Weißen Tiger in seinem Tempel.", completion = "Willkommen, {class}! Ihr seid auf der Suche nach den Waffen des Sturmgottes Ra-den?\n\nViele sind nach Pandaria gekommen, doch keiner hat sich als würdig erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43335] = { id = 43335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebensfertigkeiten", description = "Das Leben eines Jägers sollte niemals träge sein. Wer in der Wildnis lebt, weiß nie, was als Nächstes geschieht, sondern muss sich auf sein Können und seine Instinkte verlassen.\n\nZeigt mir, dass Ihr über die grundlegenden Überlebensfertigkeiten verfügt, um Euch von der Natur zu ernähren.", sourceObjective = "Beweist Eure Überlebensfertigkeiten, indem Ihr mit gehacktem Holz ein Lagerfeuer entfacht und dann ein Steak über dem offenen Feuer grillt.", progress = "Man muss essen, um in der Wildnis zu überleben.\n\nÜber offener Flamme gebratenes Wildschwein ergibt eine prächtige Mahlzeit. Auf keinen Fall aber sollte man es roh essen.\n\nAußerdem gibt es in dieser Gegend viele Beeren. Einige sind essbar, andere bereiten einem ein paar Verdauungsprobleme. Ob sie essbar sind, erkennt man häufig an ihrem Geruch: Ein süßes Aroma deutet oft darauf hin, dass eine Beere giftig ist.\n\nUnd das beste Feuerholz erhaltet Ihr von absterbenden Bäumen. Man erkennt sie ganz leicht an den blassen, lilafarbenen Blättern.", completion = "Das Lagerfeuer war ein Leichtes für Euch und das Steak perfekt angebraten. Ich bin beeindruckt... und hungrig.", sourceObjectiveStatus = "unverified-source-field" }
quests[43336] = { id = 43336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuterung des Alptraums" }
quests[43337] = { id = 43337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Met Sylvanas With Windrunner Bow" }
quests[43338] = { id = 43338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex des Ra", description = "Der Donnerkönig eroberte Pandaria mit der Macht des Titanenhüters Ra, der in der Sprache der Mogu als \"Ra-den\" bezeichnet wird. Wenn Ihr wirklich die Relikte des hohen Hüters nutzen wollt, müsst Ihr seine uralten Edikte aus dem Herzen des Mogureichs beschaffen: das Edikt des Steins, das Edikt des Feuers und das Edikt des Sturms.\n\nDiese Teile vom Kodex sind in den Guo-Lai-Hallen im Tal der Ewigen Blüten verstreut, in jedem Flügel eines.", sourceObjective = "Betretet die Guo-Lai-Hallen im Tal der Ewigen Blüten und beschafft das Edikt des Steins, das Edikt des Feuers und das Edikt des Sturms. Läutert den Bereich, indem Ihr die Geister der Mogu vernichtet.", progress = "Ich habe mich umgehört. Die einheimischen {race} fürchten sich schrecklich vor diesem Ort. Seit dem Ende von Höllschreis Pandarenfeldzug spukt es dort.\n\nHabt Ihr eine Gabe für den Weißen Tiger gefunden?", completion = "Dieser Tiger meint das wirklich ernst, oder?\n\nWährend Ihr hier wart, kamen andere zum Tempel des Weißen Tigers, um ihm ihre Gaben anzubieten. Wir scheinen also Konkurrenz zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[43340] = { id = 43340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[43341] = { id = 43341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinigung der Inseln", description = "Es gibt viele Fraktionen hier auf den Verheerten Inseln. Wir müssen sie vereinen, wenn wir eine Chance gegen die Legion haben wollen. Erweist Euch ihnen gegenüber als würdig und meldet Euch dann wieder bei mir.", sourceObjective = "Erlangt mindestens einen freundlichen Ruf bei den Fraktionen der Verheerten Inseln.", completion = "Ausgezeichnete Arbeit, {name}. Wir haben noch einen langen Weg vor uns, um diese Welt von der Legion zu befreien, aber wir sind nun einen Schritt weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[43342] = { id = 43342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette - Roteye" }
